<?php
require_role('admin','kepala_sekolah');
$monitorPeriod=($_GET['id_tahun_ajaran']??'')!==''?input_id($_GET,'id_tahun_ajaran'):(int)active_period()['id_tahun_ajaran'];
$monitorDate=($_GET['tanggal']??'')!==''?input_date($_GET,'tanggal'):date('Y-m-d');ak_period($monitorPeriod,false,$monitorDate);
$dayNames=[1=>'Senin',2=>'Selasa',3=>'Rabu',4=>'Kamis',5=>'Jumat',6=>'Sabtu',7=>'Minggu'];$monitorDay=$dayNames[(int)(new DateTimeImmutable($monitorDate))->format('N')];
$monitorWhere="j.id_tahun_ajaran=? AND j.hari=? AND j.status='aktif' AND g.status='aktif' AND k.status='aktif' AND m.status='aktif' AND w.terverifikasi=1 AND w.mulai<=? AND w.selesai>=?";$monitorArgs=[$monitorPeriod,$monitorDay,$monitorDate,$monitorDate];
foreach(['id_guru','id_kelas']as $filter)if(($_GET[$filter]??'')!==''){$monitorWhere.=' AND j.'.$filter.'=?';$monitorArgs[]=input_id($_GET,$filter);}
$monitorRoom=input_text($_GET,'ruang',20,false);if($monitorRoom!==''){$monitorWhere.=' AND j.ruang=?';$monitorArgs[]=$monitorRoom;}
$monitorJoin=' FROM jadwal j JOIN ak_penugasan w ON w.id_jadwal=j.id_jadwal JOIN guru g ON g.id_guru=j.id_guru JOIN kelas k ON k.id_kelas=j.id_kelas JOIN mata_pelajaran m ON m.id_mapel=j.id_mapel';
$monitorTotal=(int)ak_query('SELECT COUNT(*)'.$monitorJoin.' WHERE '.$monitorWhere,$monitorArgs)->fetchColumn();[$monitorPage,$monitorPages,$monitorOffset]=crud_page_bounds($monitorTotal,20,'monitor_page');
$monitorRows=ak_rows('SELECT j.*,g.nama_guru,k.nama_kelas,m.nama_mapel,(SELECT p.id FROM ak_pertemuan p WHERE p.id_jadwal=j.id_jadwal AND p.tanggal=?) id_pertemuan,(SELECT GROUP_CONCAT(DISTINCT wg.nama_guru SEPARATOR ", ") FROM ak_wali_kelas wc JOIN guru wg ON wg.id_guru=wc.id_guru WHERE wc.id_kelas=j.id_kelas AND wc.id_tahun_ajaran=j.id_tahun_ajaran AND wc.aktif=1 AND wc.mulai<=? AND wc.selesai>=?) nama_wali'.$monitorJoin.' WHERE '.$monitorWhere.' ORDER BY j.jam_mulai,g.nama_guru,j.id_jadwal LIMIT '.crud_page_limit('monitor_page').' OFFSET '.$monitorOffset,[$monitorDate,$monitorDate,$monitorDate,...$monitorArgs]);
$monitorPeriods=[];foreach(ak_rows('SELECT t.* FROM tahun_ajaran t JOIN ak_periode p USING(id_tahun_ajaran) WHERE p.terverifikasi=1 ORDER BY t.id_tahun_ajaran DESC')as $period)$monitorPeriods[$period['id_tahun_ajaran']]=$period['tahun_ajaran'].' · '.$period['semester'];
?><section class="panel" data-teaching-monitor><h2>Pemantauan guru mapel · <?=e($monitorDay)?></h2><p>Menampilkan penugasan terverifikasi pada tanggal yang dipilih, kelas/ruang, wali kelas dan status pengisian jurnal. Jadwal bukan bukti lokasi fisik atau kehadiran guru.</p>
<form method="get" class="form-grid filter"><?php ak_hidden('view',$view??'pemantauan');ak_select('id_tahun_ajaran','Periode',$monitorPeriods,$monitorPeriod);ak_field('tanggal','Tanggal',$monitorDate,'date');ak_select('id_guru','Guru mapel',crud_options('guru','id_guru','nama_guru'),$_GET['id_guru']??'',false);ak_select('id_kelas','Kelas',crud_options('kelas','id_kelas','nama_kelas'),$_GET['id_kelas']??'',false);ak_select('ruang','Ruang / lab',crud_options('ak_ruang','nama_ruang','nama_ruang'),$monitorRoom,false);?><button class="secondary">Tampilkan pemantauan</button></form>
<div class="table-scroll"><table><thead><tr><th>Jam</th><th>Guru / mapel</th><th>Kelas</th><th>Ruang</th><th>Wali kelas</th><th>Jurnal</th></tr></thead><tbody><?php foreach($monitorRows as $row):?><tr><td><?=e(substr($row['jam_mulai'],0,5).'–'.substr($row['jam_selesai'],0,5))?></td><td class="wrap"><?=e($row['nama_guru'])?><br><?=e($row['nama_mapel'])?></td><td><?=e($row['nama_kelas'])?></td><td><?=e($row['ruang']??'Belum ditetapkan')?></td><td class="wrap"><?=e($row['nama_wali']??'Belum ditetapkan')?></td><td><?php if($row['id_pertemuan']):?><a href="<?=e(ak_link('jurnal',['id'=>$row['id_pertemuan']]))?>">Sudah diisi</a><?php else:?>Belum diisi<?php endif;?></td></tr><?php endforeach;if(!$monitorRows):?><tr><td colspan="6">Tidak ada jadwal terverifikasi sesuai filter pada tanggal ini.</td></tr><?php endif;?></tbody></table></div><?php crud_pager($monitorPage,$monitorPages,$monitorTotal,'jadwal','monitor_page');?></section>
